  if (!isAdmin) {
    forbidden();
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      <h1 style={{ fontSize: '1.5rem', fontWeight: 'bold', marginBottom: '1rem' }}>Admin Dashboard</h1>
      <p>Welcome to the admin area, {session?.name}!</p>
    </main>
  );
}

